import{_ as o,r as s,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"记录排序 - October CMS - 3.x","titleTemplate":false,"description":"了解如何在列表中排序和构建记录结构。","frontmatter":{"subtitle":"了解如何在列表中排序和构建记录结构。"},"headers":[{"level":2,"title":"配置行为","slug":"配置行为","link":"#配置行为","children":[]},{"level":2,"title":"支持的模型类型","slug":"支持的模型类型","link":"#支持的模型类型","children":[{"level":3,"title":"嵌套集（Nested Set）","slug":"嵌套集-nested-set","link":"#嵌套集-nested-set","children":[]},{"level":3,"title":"简单树（Simple Tree）","slug":"简单树-simple-tree","link":"#简单树-simple-tree","children":[]},{"level":3,"title":"可排序模型（Sortable Model）","slug":"可排序模型-sortable-model","link":"#可排序模型-sortable-model","children":[]}]},{"level":2,"title":"排序关联记录","slug":"排序关联记录","link":"#排序关联记录","children":[{"level":3,"title":"可排序关联模型 Trait","slug":"可排序关联模型-trait","link":"#可排序关联模型-trait","children":[]}]}],"relativePath":"3.x/zh-cn/extend/lists/structures.md","filePath":"3.x/zh-cn/extend/lists/structures.md"}'),i={name:"3.x/zh-cn/extend/lists/structures.md"};function d(u,a,k,h,g,m){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[n(e),a[0]||(a[0]=c("h1",null,"记录排序",-1)),n(t),a[1]||(a[1]=r(`<p>October CMS 提供了对数据库记录进行排序和重新排列的功能。对于支持结构化列表的行为，您可以定义 <strong>structure</strong> 属性来启用该功能。各种<a href="./../database/traits.html">模型 Trait</a> 用于支持重新排序，包括嵌套集、简单树和可排序模型。</p><h2 id="配置行为"><a href="#配置行为" class="header-anchor">#</a> 配置行为</h2><p><a href="./list-controller.html">列表控制器</a>和<a href="./../forms/form-controller.html">关联控制器</a>后台行为目前支持使用相关定义中的 <strong>structure</strong> 属性来重新排序记录的选项。定义后，页面将显示带有拖动手柄的记录列表，允许对它们进行排序和重新组织结构。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>

<span class="token comment"># ...</span>

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showSorting</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
</code></pre></div><p>可以使用以下列出的配置属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>showTree</strong></td><td>显示父子记录的树形层次结构。默认值：<code>true</code></td></tr><tr><td><strong>treeExpanded</strong></td><td>树节点是否默认展开。默认值：<code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>显示用于重新排序记录的界面。默认值：<code>true</code></td></tr><tr><td><strong>showSorting</strong></td><td>允许排序记录，排序时禁用结构。默认值：<code>true</code></td></tr><tr><td><strong>maxDepth</strong></td><td>定义重新排序允许的最大层级数。默认值：<code>null</code></td></tr><tr><td><strong>dragRow</strong></td><td>允许拖动整行，而不仅仅是重新排序手柄。默认值：<code>true</code></td></tr><tr><td><strong>permissions</strong></td><td>当前后台用户修改结构所需的<a href="./../../extend/backend/permissions.html">权限</a>。支持单个权限的字符串或权限数组（只需满足其中一个即可授予访问权限）。</td></tr></tbody></table></div><h2 id="支持的模型类型"><a href="#支持的模型类型" class="header-anchor">#</a> 支持的模型类型</h2><p>根据需求，可以使用不同的模型接口来管理嵌套和排序的记录。行为将根据实现的 Trait 自动调整。</p><h3 id="嵌套集-nested-set"><a href="#嵌套集-nested-set" class="header-anchor">#</a> 嵌套集（Nested Set）</h3><p>当需要固定结构时，请使用 <code>NestedTree</code> Trait。这包括父子关系以及需要按特定顺序显示记录的情况。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在<a href="./../database/traits.html">数据库文档</a>中阅读有关 <code>NestedTree</code> Trait 的更多信息。</p><h3 id="简单树-simple-tree"><a href="#简单树-simple-tree" class="header-anchor">#</a> 简单树（Simple Tree）</h3><p>当需要基本的父子关系时，请使用 <code>SimpleTree</code> Trait。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在<a href="./../database/traits.html">数据库文档</a>中阅读有关 <code>SimpleTree</code> Trait 的更多信息。</p><h3 id="可排序模型-sortable-model"><a href="#可排序模型-sortable-model" class="header-anchor">#</a> 可排序模型（Sortable Model）</h3><p>当需要按特定顺序显示记录时，请使用 <code>Sortable</code> Trait。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在<a href="./../database/traits.html">数据库文档</a>中阅读有关 <code>Sortable</code> Trait 的更多信息。</p><h2 id="排序关联记录"><a href="#排序关联记录" class="header-anchor">#</a> 排序关联记录</h2><p>可以使用<a href="./../forms/relation-controller.html">关联控制器</a>的 <strong>structure</strong> 属性来排序关联记录。下面列出了支持的关联类型。</p><ul><li><a href="./../database/relations.html#relation-one-to-many">一对多（Has Many）</a>在关联模型上使用 <code>Sortable</code> Trait。</li><li><a href="./../database/relations.html#relation-many-to-many">多对多（Belongs To Many）</a>在父模型上使用 <code>SortableRelation</code> Trait（见下文）。</li></ul><h3 id="可排序关联模型-trait"><a href="#可排序关联模型-trait" class="header-anchor">#</a> 可排序关联模型 Trait</h3><p>当需要在中间表内排序记录时（例如<a href="./../database/relations.html#many-to-many">多对多（Belongs To Many）</a>关联类型），请使用 <code>SortableRelation</code> 模型 Trait。此 Trait 要求在关联中定义 <code>pivotSortable</code> 属性，其值为中间表中的可排序列名。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SortableRelation</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var array belongsToMany
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name static-context">Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;users_roles&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;pivotSortable&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>然后在关联配置中，您应该启用 <code>showReorder</code> 属性并禁用 <code>showTree</code> 属性。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token comment">#...</span>
    <span class="token key atrule">structure</span><span class="token punctuation">:</span>
        <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,28))])}const T=o(i,[["render",d]]);export{y as __pageData,T as default};
